package io.github.mith_mmk.wml2viewer.platform.codec

import android.util.Base64

/**
 * Rights-clear codec probes generated from four solid-color pixels.
 *
 * These are decode probes only. OS encoder support is measured separately by
 * encoding a runtime bitmap and decoding the result again.
 */
internal object AndroidCodecProbeFixtures {
    val encoded: Map<CodecFormat, ByteArray> by lazy(LazyThreadSafetyMode.PUBLICATION) {
        mapOf(
            CodecFormat.GIF to decode(GIF),
            CodecFormat.BMP to decode(BMP),
            CodecFormat.ICO to decode(ICO),
            CodecFormat.HEIF to decode(HEIF),
            CodecFormat.AVIF to decode(AVIF),
            CodecFormat.DNG to decode(DNG),
        )
    }

    private fun decode(value: String): ByteArray = Base64.decode(value, Base64.DEFAULT)
    private fun decode(parts: List<String>): ByteArray = decode(parts.joinToString(separator = ""))

    private const val GIF =
        "R0lGODlhAgACAPEDAP8AAAD/AAAA/////yH5BAAAAAAALAAAAAACAAIAAAIDRDQFADs="

    private const val BMP =
        "Qk1+AAAAAAAAAHYAAAAoAAAAAgAAAAIAAAABAAQAAAAAAAgAAAAAAAAAAAAAABAAAAAQAAAAAAD/AAD/AAD/AAAA////AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAACMAAAABAAAA"

    private const val ICO =
        ""

    private const val AVIF =
        ""

    // Project-owned WML2Viewer sample reviewed to contain no mutable device metadata.
    // Split to stay below the JVM constant-pool UTF-8 entry limit.
    private val HEIF = listOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )

    // Synthetic 16x16 Bayer DNG generated with gamut-dng (MIT OR Apache-2.0).
    private const val DNG =
        ""
}
